function Donut({ v, size, center, sub, nw }: { v: number[]; size: number; center: string; sub?: string; nw?: boolean }) {
  const t = useGrokTheme();
  const d = t.dataviz;
  const colors = SYS; void d;
  const sum = v.reduce((a, b) => a + b, 0) || 1;
  let off = 0;
  const pt = (f: number, rad: number) => { const a = f * 2 * Math.PI - Math.PI / 2; return `${(50 + rad * Math.cos(a)).toFixed(3)} ${(50 + rad * Math.sin(a)).toFixed(3)}`; };
  const arc = (f0: number, f1: number) => { const big = f1 - f0 > 0.5 ? 1 : 0; return `M ${pt(f0, 47)} A 47 47 0 ${big} 1 ${pt(f1, 47)} L ${pt(f1, 33)} A 33 33 0 ${big} 0 ${pt(f0, 33)} Z`; };
  return (
    <svg viewBox="0 0 100 100" style={{ width: '100%', maxWidth: size, display: 'block', margin: '0 auto' }}>
      <title>{CATS.map((name, i) => `${name}: ${v[i]}`).join('\n')}</title>
      <path d={arc(0, 0.99999)} style={{ fill: t.border.subtle }} />
      {v.map((x, i) => {
        if (!x) return null;
        const a0 = off / sum;
        off += x;
        const a1 = Math.min(off / sum, 0.99999);
        return <path key={i} d={arc(a0, a1)} style={{ fill: colors[i] }} />;
      })}
      <text x="50" y={sub ? (nw && sub === 'за' ? 48 : 50) : 55} textAnchor="middle" fontSize="16" fontWeight={600} style={{ fill: t.text.primary, fontFamily: t.font.family }}>{center}</text>
      {sub && <text x="50" y={nw && sub === 'за' ? 64 : 63} textAnchor="middle" fontSize={nw && sub === 'за' ? 11 : 8} fontWeight={nw && sub === 'за' ? 600 : 400} style={{ fill: t.text.secondary, fontFamily: t.font.family }}>{sub}</text>}
    </svg>
  );
}

